MOD = 10**9 + 7

def count_ways(n, k):
    def binomial_coefficient(n, k):
        if k > n:
            return 0
        if k == 0 or k == n:
            return 1
        k = min(k, n - k)
        res = 1
        for i in range(k):
            res = res * (n - i) // (i + 1)
        return res

    def stirling_second_kind(n, k):
        if n == k == 0:
            return 1
        if n == 0 or k == 0:
            return 0
        return (k * stirling_second_kind(n - 1, k) + stirling_second_kind(n - 1, k - 1)) % MOD

    def ways_to_fill_grid(n, k):
        total_ways = pow(k, n * n, MOD)
        for i in range(1, n + 1):
            total_ways -= binomial_coefficient(n, i) * pow(k - 1, n * n, MOD)
            total_ways %= MOD
        for i in range(1, n + 1):
            total_ways += binomial_coefficient(n, i) * binomial_coefficient(n, i) * pow(k - 1, n * n - i * i, MOD)
            total_ways %= MOD
        return total_ways

    return ways_to_fill_grid(n, k)

